Section CriSegs.
Context {fx : FPState} {AL : AllocLayout} {CL : CallocLayout} {ASR : AllocSure}.
Context {PINS : @LeptPins AL LLU16} {P16 : V2Pins}.
#[local] Notation "'u'" := bv_unsigned (only parsing).
#[local] Notation w4 x := (word_to_le_bytes 4 x) (only parsing).

(* [comment removed for export] *)
Definition FRM5 (m : word -> option byte) (s : Z) (ret : word) (regs : bvmap 5 word) : word -> option byte :=
  wbytes (wbytes (wbytes (wbytes (wbytes m
    (Z_to_bv 64 (s - 8)) (word_to_le_bytes 8 ret))
    (Z_to_bv 64 (s - 16)) (word_to_le_bytes 8 (getr regs 8)))
    (Z_to_bv 64 (s - 24)) (word_to_le_bytes 8 (getr regs 9)))
    (Z_to_bv 64 (s - 32)) (word_to_le_bytes 8 (getr regs 18)))
    (Z_to_bv 64 (s - 40)) (word_to_le_bytes 8 (getr regs 19)).
Definition frame5 (s : Z) (ret : word) (r0 : bvmap 5 word) : list (Z * word) :=
  [((s - 8)%Z, ret); ((s - 16)%Z, getr r0 8); ((s - 24)%Z, getr r0 9); ((s - 32)%Z, getr r0 18); ((s - 40)%Z, getr r0 19)].
(* [comment removed for export] *)
Definition DIM3c (m : word -> option byte) (wc hc dc w h d : Z) : word -> option byte :=
  wbytes (wbytes (wbytes (wbytes (wbytes (wbytes m
    (Z_to_bv 64 wc) (w4 (Z_to_bv 64 0)))
    (Z_to_bv 64 hc) (w4 (Z_to_bv 64 0)))
    (Z_to_bv 64 dc) (w4 (Z_to_bv 64 0)))
    (Z_to_bv 64 wc) (w4 (Z_to_bv 64 w)))
    (Z_to_bv 64 hc) (w4 (Z_to_bv 64 h)))
    (Z_to_bv 64 dc) (w4 (Z_to_bv 64 d)).
(* [comment removed for export] *)
Definition DIM9 (m : word -> option byte) (s w h : Z) : word -> option byte :=
  DIM3c (DIM3c (DIM3c m (s - 44) (s - 56) (s - 68) w h 8) (s - 48) (s - 60) (s - 72) w h 8) (s - 52) (s - 64) (s - 76) w h 8.

