(* [comment removed for export] *)
Definition cri_cells (m : word -> option byte) (s w h : Z) : Prop :=
  rdn SEGS m (Z_to_bv 64 (s - 44)) 4 = Some (w4 (Z_to_bv 64 w)) /\ rdn SEGS m (Z_to_bv 64 (s - 48)) 4 = Some (w4 (Z_to_bv 64 w)) /\
  rdn SEGS m (Z_to_bv 64 (s - 52)) 4 = Some (w4 (Z_to_bv 64 w)) /\ rdn SEGS m (Z_to_bv 64 (s - 56)) 4 = Some (w4 (Z_to_bv 64 h)) /\
  rdn SEGS m (Z_to_bv 64 (s - 60)) 4 = Some (w4 (Z_to_bv 64 h)) /\ rdn SEGS m (Z_to_bv 64 (s - 64)) 4 = Some (w4 (Z_to_bv 64 h)) /\
  rdn SEGS m (Z_to_bv 64 (s - 68)) 4 = Some (w4 (Z_to_bv 64 8)) /\ rdn SEGS m (Z_to_bv 64 (s - 72)) 4 = Some (w4 (Z_to_bv 64 8)) /\
  rdn SEGS m (Z_to_bv 64 (s - 76)) 4 = Some (w4 (Z_to_bv 64 8)).
Lemma cri_cells_DIM9 : forall m s w h, (80 <= s)%Z -> (s < 2 ^ 64)%Z -> cri_cells (DIM9 m s w h) s w h.
