Section Segs.
Variable rom : word -> option byte.

  (* [comment removed for export] *)
  Lemma ci_A0 : forall regs m (s : Z) (ret : word),
    (80 <= s)%Z -> (s < 2 ^ 64)%Z -> store_ok SEGS m (Z_to_bv 64 (s - 80)) 80 = true ->
    getr regs 2 = Z_to_bv 64 s -> getr regs 1 = ret ->
    exists regs',
      msteps SEGS (mkst regs (0x1cae0 : word) m rom) (mkst regs' (0x1caf8 : word) (FRM5 m s ret regs) rom)
      /\ getr regs' 2 = Z_to_bv 64 (s - 80)
      /\ regs_agree (fun x => In x [2]%list) regs regs'.
Proof.
    intros regs m s ret Hs Hs64 SOK H2 H1.
    eexists. split.
    - unfold FRM5.
      zv F_1bba4 D_1bba4 (Z_to_bv 64 (s - 80)).
      stepST F_1bba8 D_1bba8 (Z_to_bv 64 (s - 8)) ret ltac:(sok_in SOK).
      stepST F_1bbac D_1bbac (Z_to_bv 64 (s - 16)) (getr regs 8) ltac:(sok_in SOK).
      stepST F_1bbb0 D_1bbb0 (Z_to_bv 64 (s - 24)) (getr regs 9) ltac:(sok_in SOK).
      stepST F_1bbb4 D_1bbb4 (Z_to_bv 64 (s - 32)) (getr regs 18) ltac:(sok_in SOK).
      stepST F_1bbb8 D_1bbb8 (Z_to_bv 64 (s - 40)) (getr regs 19) ltac:(sok_in SOK).
      apply mst_refl.
    - repeat split; gres; pin; try reflexivity. solve_regs_agree.
Qed.

  (* [comment removed for export] *)
  Lemma ci_NT : forall regs r0 m (s msg : Z) (ret : word),
    (80 <= s)%Z -> (s < 2 ^ 64)%Z -> cellsZ m (frame5 s ret r0) ->
    getr regs 2 = Z_to_bv 64 (s - 80) -> getr regs 10 = Z_to_bv 64 msg -> getr regs 11 = Z_to_bv 64 0x1100d ->
    exists regs',
      msteps SEGS (mkst regs (0x1cc58 : word) m rom) (mkst regs' (0x17ec4 : word) m rom)
      /\ getr regs' 2 = Z_to_bv 64 s /\ getr regs' 1 = ret /\ getr regs' 10 = Z_to_bv 64 msg /\ getr regs' 11 = Z_to_bv 64 0x1100d /\ getr regs' 12 = Z_to_bv 64 0
      /\ (forall x, In x [8; 9; 18; 19]%bv -> getr regs' x = getr r0 x)
