  (* [comment removed for export] *)
  Lemma ci_NR : forall regs m,
    rdn SEGS m (Z_to_bv 64 0x44e98) 8 = Some (Z_to_le_bytes 8 0x45f08) -> rdn SEGS m (Z_to_bv 64 0x45f08) 4 = Some (Z_to_le_bytes 4 3) ->
    getr regs 10 = Z_to_bv 64 0 ->
    exists regs',
      msteps SEGS (mkst regs (0x1caf8 : word) m rom) (mkst regs' (0x1cc58 : word) m rom)
      /\ getr regs' 10 = Z_to_bv 64 0x11816 /\ getr regs' 11 = Z_to_bv 64 0x1100d
      /\ regs_agree (fun x => In x [10; 11]%list) regs regs'.
Proof.
    intros regs m RG RS H10.
    eexists. split.
    - stepb_tk F_1bbbc D_1bbbc ltac:(condZ).
      sn F_1bca8 D_1bca8.
      stepLD F_1bcac D_1bcac (Z_to_le_bytes 8 0x45f08) (Z_to_bv 64 0x45f08) ltac:(addr_norm; exact RG) ltac:(apply lez8; lia).
      stepLD F_1bcb0 D_1bcb0 (Z_to_le_bytes 4 3) (Z_to_bv 64 3) ltac:(addr_norm; exact RS) ltac:(apply lez4; lia).
      sn F_1bcb4 D_1bcb4.
      stepb_ft F_1bcb8 D_1bcb8 ltac:(cond_compute).
      sn F_1bcbc D_1bcbc.
      sn F_1bcc0 D_1bcc0.
      sn F_1bcc4 D_1bcc4.
      sn F_1bcc8 D_1bcc8.
      sn F_1bccc D_1bccc.
      apply mst_refl.
    - repeat split; gres; pin; try reflexivity. solve_regs_agree.
Qed.

