  Lemma ci_NG : forall regs m (pr : Z),
    rdn SEGS m (Z_to_bv 64 0x44e98) 8 = Some (Z_to_le_bytes 8 0x45f08) -> rdn SEGS m (Z_to_bv 64 0x45f08) 4 = Some (Z_to_le_bytes 4 3) ->
    (1 <= pr < 2 ^ 64)%Z -> getr regs 10 = Z_to_bv 64 pr -> getr regs 11 = Z_to_bv 64 0 ->
    exists regs',
      msteps SEGS (mkst regs (0x1caf8 : word) m rom) (mkst regs' (0x1cc58 : word) m rom)
      /\ getr regs' 10 = Z_to_bv 64 0x1101f /\ getr regs' 11 = Z_to_bv 64 0x1100d
      /\ regs_agree (fun x => In x [10; 11]%list) regs regs'.
Proof.
    intros regs m pr RG RS Hpr H10 H11.
    eexists. split.
    - stepb_ft F_1bbbc D_1bbbc ltac:(condZ).
      stepb_tk F_1bbc0 D_1bbc0 ltac:(condZ).
      sn F_1bcd0 D_1bcd0.
      stepLD F_1bcd4 D_1bcd4 (Z_to_le_bytes 8 0x45f08) (Z_to_bv 64 0x45f08) ltac:(addr_norm; exact RG) ltac:(apply lez8; lia).
      stepLD F_1bcd8 D_1bcd8 (Z_to_le_bytes 4 3) (Z_to_bv 64 3) ltac:(addr_norm; exact RS) ltac:(apply lez4; lia).
      sn F_1bcdc D_1bcdc.
      stepb_ft F_1bce0 D_1bce0 ltac:(cond_compute).
      sn F_1bce4 D_1bce4.
      sn F_1bce8 D_1bce8.
      sn F_1bcec D_1bcec.
      sn F_1bcf0 D_1bcf0.
